package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class PictureArithmeticTest {
 @Test public void finiteMixedContextsExhaustBeforeOldest(){Generator g=new Generator(new Random(123));var limits=GlobalCurriculum.limits("england-primary-2021-v1",PictureArithmetic.ID,2);List<String> recent=new ArrayList<>();Set<Integer> operations=new HashSet<>(),results=new HashSet<>();for(int i=0;i<462;i++){Question q=g.next(PictureArithmetic.ID,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=PictureArithmetic.read(q);operations.add(v[2]);results.add(v[3]);int expected=q.diagram.type.equals("putButtons")?(int)(q.diagram.values[0]+q.diagram.values[1]):(int)(q.diagram.values[0]-q.diagram.values[1]);q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertFalse(new Checker().check(q,List.of(),List.of(""+(expected+1))).correct());assertTrue(q.choices.isEmpty());HelpPlan p=HelpPlan.forQuestion(q);assertEquals(4,p.size());assertFalse(p.canTransfer());assertTrue(p.step(0).accepts(v[2]==1?"put":"take"));assertTrue(p.step(1).accepts(""+v[0]));assertTrue(p.step(2).accepts(""+v[1]));assertTrue(p.step(3).accepts(""+expected));for(int s=0;s<4;s++)assertFalse(p.step(s).before.matches(".*\\d.*"));}assertEquals(Set.of(0,1),operations);assertEquals(21,results.size());assertEquals(recent.get(0),g.next(PictureArithmetic.ID,recent,false,limits).signature());}
 @Test public void publicPictureAndStoryMustAgreeIncludingZero(){for(boolean put:new boolean[]{true,false})for(int[] values:new int[][]{{0,0},{20,0},{10,10}}){Question q=PictureArithmetic.make(put,values[0],values[1]);assertNotNull(PictureArithmetic.read(q));}Question q=PictureArithmetic.make(true,3,5);q.diagram.values[1]=6;assertNull(PictureArithmetic.read(q));q=PictureArithmetic.make(false,8,3);q.diagram.values[0]=Double.NaN;assertNull(PictureArithmetic.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("5")).status);Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(PictureArithmetic.ID,2));assertFalse(GlobalCurriculum.pack(p).inGrade(PictureArithmetic.ID,1));}
}
